arguments.command:
node -e '
const fs = require("fs");
const files = ["a.txt", "b.txt", "c.txt"];
const rows = files.map((f) => {
  const raw = fs.readFileSync(f, "utf8");
  const text = raw.trim();
  if (!text) throw new Error(`${f}: empty file`);
  const lines = text.split(/\r?\n/).filter((l) => l.trim() !== "");
  if (lines.length !== 1) throw new Error(`${f}: expected exactly 1 line, got ${lines.length}`);
  const m = lines[0].match(/^([A-Za-z]+) population:\s*(\d+)$/);
  if (!m) throw new Error(`${f}: unrecognized format: ${JSON.stringify(lines[0])}`);
  const n = Number(m[2]);
  if (!Number.isInteger(n) || n < 0) throw new Error(`${f}: bad population ${m[2]}`);
  return { file: f, label: m[1], population: n };
});
const labels = rows.map((r) => r.label);
const expected = ["Alpha", "Beta", "Gamma"];
if (JSON.stringify(labels) !== JSON.stringify(expected)) throw new Error(`label cross-check failed: ${labels}`);
const total = rows.reduce((s, r) => s + r.population, 0);
const sum = rows.map((r) => r.population).join(" + ") + " = " + total;
fs.writeFileSync("answer.json", JSON.stringify({ total }, null, 2) + "\n");
console.log(JSON.stringify({ rows, sum, total, typeofTotal: typeof total }, null, 2));
'

node -e '
const fs = require("fs"), assert = require("assert");
const answer = JSON.parse(fs.readFileSync("answer.json", "utf8"));
const recomputed = ["a.txt","b.txt","c.txt"].map((f) => Number(fs.readFileSync(f,"utf8").match(/:\s*(\d+)/)[1]));
const expected = recomputed.reduce((s,n)=>s+n,0);
assert.deepStrictEqual(Object.keys(answer), ["total"], "unexpected keys: " + Object.keys(answer));
assert.strictEqual(typeof answer.total, "number");
assert.ok(Number.isFinite(answer.total));
assert.strictEqual(answer.total, 60);
assert.strictEqual(answer.total, expected);
console.log("PASS keys=" + JSON.stringify(Object.keys(answer)) + " total=" + answer.total + " (typeof " + typeof answer.total + ") recomputed=" + recomputed.join("+") + "=" + expected);
' && echo "--- answer.json on disk ---" && cat answer.json

