node -e '
const fs=require("fs");
const raw=fs.readFileSync("answer.json","utf8");
const a=JSON.parse(raw);
const checks={
  validJSON:true,
  numericKeys:[ "total" ],
  totalIsNumber: typeof a.total === "number",
  totalNotString: a.total !== "60",
  finite: Number.isFinite(a.total),
  exactKeys: JSON.stringify(Object.keys(a))===JSON.stringify(["total"]),
  equals60: a.total===60,
  rawBytes: Buffer.byteLength(raw)
};
console.log(JSON.stringify(checks));
if(!a.total || checks.totalIsNumber!==true || !checks.exactKeys) process.exit(1);
' && echo "files present:" && ls -1
